private void xrLabel10_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
  xrLabel10.Visible = false;
            object nipti = GetCurrentColumnValue("NDERMARJENIPT");
            if (nipti != DBNull.Value)
            { 
                int gjatesiNipt = nipti.ToString().Length;
                Char[] arr = new Char[gjatesiNipt];
                arr = nipti.ToString().ToCharArray();
                for (int i = 0; i < gjatesiNipt; i++)
                {
                    XRLabel label = FindControl("nr" + (i + 1), true) as XRLabel;
                    if(label != null)
                        label.Text = arr[i].ToString();
                }
            }
}

